// Generated by AI, edited by humans
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const SRC_DIR = path.join(__dirname, 'src');

function findHtmlPages() {
    return fs
        .readdirSync(SRC_DIR)
        .filter((file) => file.endsWith('.html'))
        .sort((a, b) => (a === 'index.html' ? -1 : b === 'index.html' ? 1 : a.localeCompare(b)))
        .map((file) => path.join('src', file));
}

export async function buildPages({ emptyOutDir = true } = {}) {
    const htmlPages = findHtmlPages();

    for (let i = 0; i < htmlPages.length; i++) {
        await build({
            build: {
                emptyOutDir: i === 0 ? emptyOutDir : false,
                rollupOptions: {
                    input: htmlPages[i],
                },
            },
        });
    }
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, '/'))) {
    const emptyOutDir = process.argv.includes('--emptyOutDir');
    await buildPages({ emptyOutDir });
}
